package subtitle

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"golang.org/x/text/encoding/simplifiedchinese"
)

func gbkDecoder() func([]byte) (string, error) {
	dec := simplifiedchinese.GBK.NewDecoder()
	return func(b []byte) (string, error) {
		out, err := dec.Bytes(b)
		return string(out), err
	}
}

// ADR-007 出口条件：ASS roundtrip 保真测试（解析→序列化→逐字段 diff）。
const sampleASS = `[Script Info]
; Script generated by Index-VT roundtrip fixture
Title: EP12
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080
ScaledBorderAndShadow: yes

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,思源黑体 CN Medium,60,&H00FFFFFF,&H000000FF,&H00000000,&H64000000,0,0,0,0,100,100,0,0,1,2,1,2,80,80,60,1
Style: Title,优设标题黑,80,&H0000D6BE,&H000000FF,&H00202A38,&H64000000,-1,0,0,0,100,100,1,0,1,3,0,8,60,60,50,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:01.00,0:00:03.50,Default,,0,0,0,,你们看，这就是传说中的{\i1}王妃{\i0}。
Dialogue: 0,0:03:14.24,0:03:16.90,Title,,0,0,0,,这个嘛……说来话长。
`

func TestASSRoundtripFidelity(t *testing.T) {
	dir := t.TempDir()
	src := filepath.Join(dir, "ep12.ass")
	if err := os.WriteFile(src, []byte(sampleASS), 0o644); err != nil {
		t.Fatal(err)
	}
	engine := NewEngine(nil)
	doc, err := engine.Open(src)
	if err != nil {
		t.Fatal(err)
	}
	if doc.Format != FormatASS {
		t.Fatalf("format=%s", doc.Format)
	}
	if len(doc.Cues) != 2 {
		t.Fatalf("cues=%d want 2", len(doc.Cues))
	}
	// 样式捕获（自捕获层）
	if len(doc.Styles) != 2 {
		t.Fatalf("styles=%d want 2", len(doc.Styles))
	}
	styleNames := map[string]bool{}
	for _, s := range doc.Styles {
		styleNames[s.Name] = true
	}
	if !styleNames["Default"] || !styleNames["Title"] {
		t.Fatalf("样式缺失: %v", styleNames)
	}
	// roundtrip：未修改导出
	out, err := engine.ExportToBytes(doc.ID, ExportOptions{Format: FormatASS})
	if err != nil {
		t.Fatal(err)
	}
	outStr := string(out)
	// [Script Info] 原始字段保真
	for _, want := range []string{"PlayResX: 1920", "PlayResY: 1080", "ScaledBorderAndShadow: yes", "ScriptType: v4.00+"} {
		if !strings.Contains(outStr, want) {
			t.Fatalf("Script Info 丢失字段 %q\n%s", want, outStr)
		}
	}
	// [V4+ Styles] 全字段保真（逐字段：Style 行原文回填）
	for _, want := range []string{
		"Style: Default,思源黑体 CN Medium,60,&H00FFFFFF,&H000000FF,&H00000000,&H64000000,0,0,0,0,100,100,0,0,1,2,1,2,80,80,60,1",
		"Style: Title,优设标题黑,80,&H0000D6BE,&H000000FF,&H00202A38,&H64000000,-1,0,0,0,100,100,1,0,1,3,0,8,60,60,50,1",
	} {
		if !strings.Contains(outStr, want) {
			t.Fatalf("Style 行保真失败，缺:\n%s\n--- got ---\n%s", want, outStr)
		}
	}
	// 事件文本与时间（astisub Events 段：Marked=0 前缀，时间 2 位小时等价格式）
	for _, want := range []string{
		"00:00:01.00,00:00:03.50,Default,",
		"00:03:14.24,00:03:16.90,Title,",
	} {
		if !strings.Contains(outStr, want) {
			t.Fatalf("Dialogue 保真失败，缺 %q\n%s", want, outStr)
		}
	}
	// 覆写标签保真
	if !strings.Contains(outStr, "{\\i1}王妃{\\i0}") {
		t.Fatalf("覆写标签丢失:\n%s", outStr)
	}
}

// F-15：SRT 时间轴 ms 级一致（含逗号毫秒格式）。
const sampleSRT = "1\n00:00:01,000 --> 00:00:03,500\n你们看，这就是传说中的王妃。\n\n2\n00:03:14,240 --> 00:03:16,900\n这个嘛……说来话长。\n"

func TestSRTRoundtrip(t *testing.T) {
	dir := t.TempDir()
	src := filepath.Join(dir, "ep12.srt")
	if err := os.WriteFile(src, []byte(sampleSRT), 0o644); err != nil {
		t.Fatal(err)
	}
	engine := NewEngine(nil)
	doc, err := engine.Open(src)
	if err != nil {
		t.Fatal(err)
	}
	if len(doc.Cues) != 2 {
		t.Fatalf("cues=%d", len(doc.Cues))
	}
	c1 := doc.Cues[0]
	if c1.StartMs != 1000 || c1.EndMs != 3500 {
		t.Fatalf("cue1 时间=%d-%d", c1.StartMs, c1.EndMs)
	}
	if c1.Original != "你们看，这就是传说中的王妃。" {
		t.Fatalf("cue1 文本=%q", c1.Original)
	}
	out, err := engine.ExportToBytes(doc.ID, ExportOptions{Format: FormatSRT})
	if err != nil {
		t.Fatal(err)
	}
	outStr := string(out)
	if strings.HasPrefix(outStr, "\xEF\xBB\xBF") {
		t.Fatal("导出不应带 BOM（02 文档 §11.6）")
	}
	if !strings.Contains(outStr, "00:00:01,000 --> 00:00:03,500") {
		t.Fatalf("时间轴保真失败:\n%s", outStr)
	}
	if !strings.Contains(outStr, "这个嘛……说来话长。") {
		t.Fatalf("文本保真失败:\n%s", outStr)
	}
}

// F-16：VTT 时间分隔符为点。
func TestVTTExport(t *testing.T) {
	engine := NewEngine(nil)
	doc, _ := engine.Open(makeTemp(t, "x.srt", sampleSRT))
	out, err := engine.ExportToBytes(doc.ID, ExportOptions{Format: FormatVTT})
	if err != nil {
		t.Fatal(err)
	}
	s := string(out)
	if !strings.Contains(s, "WEBVTT") {
		t.Fatalf("缺 WEBVTT 头:\n%s", s)
	}
	if !strings.Contains(s, "00:00:01.000 --> 00:00:03.500") {
		t.Fatalf("VTT 应使用点毫秒:\n%s", s)
	}
}

// F-16：GBK 导出（走真实文件导出路径）。
func TestGBKExport(t *testing.T) {
	engine := NewEngine(nil)
	doc, _ := engine.Open(makeTemp(t, "x.srt", sampleSRT))
	outPath := filepath.Join(t.TempDir(), "out_gbk.srt")
	if err := engine.Export(doc.ID, ExportOptions{Format: FormatSRT, Encoding: "gbk", OutPath: outPath}); err != nil {
		t.Fatal(err)
	}
	raw, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatal(err)
	}
	// 不应再有 UTF-8 BOM；GBK 回读应得到原文
	if s := bytesToGBKSafe(raw); !strings.Contains(s, "王妃") {
		t.Fatalf("GBK 编码回读失败: %q", s)
	}
}

func bytesToGBKSafe(b []byte) string {
	// 测试辅助：GBK → UTF-8
	dec := gbkDecoder()
	out, err := dec(b)
	if err != nil {
		return ""
	}
	return out
}

// 双语双行（F-15：原文行上/译文行下）。
func TestBilingualDualLine(t *testing.T) {
	engine := NewEngine(nil)
	doc, _ := engine.Open(makeTemp(t, "x.srt", sampleSRT))
	doc.Cues[0].Translated = "Look, this is the legendary Wang Fei."
	out, err := engine.ExportToBytes(doc.ID, ExportOptions{Format: FormatSRT, Bilingual: BilingualDualLine})
	if err != nil {
		t.Fatal(err)
	}
	s := string(out)
	if !strings.Contains(s, "你们看，这就是传说中的王妃。\nLook, this is the legendary Wang Fei.") {
		t.Fatalf("双语双行失败:\n%s", s)
	}
}

// LRC：解析 + 结束时间约定 + 导出。
const sampleLRC = "[ti:测试]\n[offset:0]\n[00:01.00]第一句歌词\n[00:05.20][00:10.00]第二句歌词\n"

func TestLRCRoundtrip(t *testing.T) {
	engine := NewEngine(nil)
	doc, err := engine.Open(makeTemp(t, "song.lrc", sampleLRC))
	if err != nil {
		t.Fatal(err)
	}
	if doc.Format != FormatLRC {
		t.Fatalf("format=%s", doc.Format)
	}
	if len(doc.Cues) != 3 {
		t.Fatalf("cues=%d want 3（多时间标签展开）", len(doc.Cues))
	}
	c0 := doc.Cues[0]
	if c0.StartMs != 1000 {
		t.Fatalf("start=%d", c0.StartMs)
	}
	// 下一条 start − 1ms
	if c0.EndMs != 5200-1 {
		t.Fatalf("LRC 结束约定失败: end=%d", c0.EndMs)
	}
	last := doc.Cues[len(doc.Cues)-1]
	if last.EndMs != last.StartMs+5000 {
		t.Fatalf("末条 +5s 约定失败: end=%d", last.EndMs)
	}
	out, err := engine.ExportToBytes(doc.ID, ExportOptions{Format: FormatLRC})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(out), "[00:01.00]第一句歌词") {
		t.Fatalf("LRC 导出失败:\n%s", out)
	}
}

// GBK 输入解码。
func TestGBKImport(t *testing.T) {
	raw := []byte{0xC4, 0xE3, 0xBA, 0xC3} // "你好" GBK
	content := "1\n00:00:01,000 --> 00:00:02,000\n" + string(raw) + "\n"
	engine := NewEngine(nil)
	doc, err := engine.Open(makeTemp(t, "g.srt", content))
	if err != nil {
		t.Fatal(err)
	}
	if doc.Encoding != "gbk" {
		t.Fatalf("encoding=%s", doc.Encoding)
	}
	if doc.Cues[0].Original != "你好" {
		t.Fatalf("GBK 解码失败: %q", doc.Cues[0].Original)
	}
}

// ---------- 覆写标签（02 文档 §11.2） ----------

func TestOverrideTagsStripReinsert(t *testing.T) {
	orig := "{\\i1}斜体文本{\\i0}"
	clean, tags := StripOverrideTags(orig)
	if clean != "斜体文本" || len(tags) != 2 {
		t.Fatalf("strip: %q %v", clean, tags)
	}
	back, needsCheck := ReinsertOverrideTags("italic text", tags[:1])
	if needsCheck {
		t.Fatal("单标签回填不应需要检查")
	}
	if back != "{\\i1}italic text" {
		t.Fatalf("回填失败: %q", back)
	}
	// 标签数变化 → 丢弃 + 需检查
	_, needsCheck = ReinsertOverrideTags("文本", tags)
	if !needsCheck {
		t.Fatal("两标签对单行译文应标记需检查")
	}
}

func makeTemp(t *testing.T, name, content string) string {
	t.Helper()
	p := filepath.Join(t.TempDir(), name)
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	return p
}

// ---------- Task 1.16：字幕保真（B26 ASS \N / B27 BOM / B28 LRC） ----------
// 夹具按真实函数命名（parseASS / serializeAstisubOpt / decodeText / parseLRC），保持最小。

// mustParseASS 用真实 parseASS 构造 ASS 文档夹具。
func mustParseASS(t *testing.T, src string) *SubtitleDoc {
	t.Helper()
	cues, styles, headerLines, eventsFormat, stylesSection, stylesFormat, err := parseASS(src)
	if err != nil {
		t.Fatalf("parseASS: %v", err)
	}
	if len(cues) == 0 {
		t.Fatal("ASS 夹具未解析出 cue")
	}
	return &SubtitleDoc{
		ID: "ass-test", Format: FormatASS, Encoding: "utf-8",
		Cues: cues, Styles: styles, HeaderLines: headerLines, EventsLines: eventsFormat,
		StylesSection: stylesSection, StylesFormat: stylesFormat,
	}
}

// mustSerializeASS 走真实 ASS 序列化路径并返回字符串。
func mustSerializeASS(t *testing.T, doc *SubtitleDoc, opt ExportOptions) string {
	t.Helper()
	out, err := NewEngine(nil).serializeAstisubOpt(doc, opt.Format, opt.Bilingual, false)
	if err != nil {
		t.Fatalf("序列化失败: %v", err)
	}
	return string(out)
}

const assEvents10 = "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text"

// assSrc 组装最小 ASS 源（Script Info + 指定 Events Format + 一条 Dialogue）。
func assSrc(eventsFormat, dialogue string) string {
	return "[Script Info]\nScriptType: v4.00+\n\n[Events]\n" + eventsFormat + "\n" + dialogue + "\n"
}

// B26：ASS `\N` 解析必须转成真实换行（否则 textToLines 按 \n 切分把整段当一行），
// 序列化必须还原成 `\N` —— 解析与序列化严格互逆。
func TestASSMultilineRoundtrip(t *testing.T) {
	doc := mustParseASS(t, assSrc(assEvents10,
		`Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,第一行\N第二行`))
	if n := strings.Count(doc.Cues[0].Original, "\n"); n != 1 {
		t.Fatalf(`ASS \N 未转成换行：Original=%q`, doc.Cues[0].Original)
	}
	out := mustSerializeASS(t, doc, ExportOptions{Format: FormatASS, Bilingual: BilingualTranslationOnly})
	if !strings.Contains(out, `第一行\N第二行`) {
		t.Fatalf("序列化未还原 \\N：%s", out)
	}
	if !strings.Contains(out, "Dialogue: 0,00:00:01.00,00:00:02.00,Default,,0,0,0,,第一行\\N第二行") {
		t.Fatalf("Dialogue 行未按 \\N 写出：%s", out)
	}
}

// B26：`\n`（软换行）与 `\h`（硬空格）按同一约定归一化。
func TestASSSoftBreakAndHardSpace(t *testing.T) {
	doc := mustParseASS(t, assSrc(assEvents10,
		`Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,甲\n乙\h丙`))
	if got := doc.Cues[0].Original; got != "甲\n乙 丙" {
		t.Fatalf("软换行/硬空格归一化失败：%q", got)
	}
}

// B26：v4.00 SSA 的 ScriptType 与原 Format 字段数必须保真；
// 强推 V4+ 23 字段 Format 会让播放器按错误字段数解析。
func TestSSAFormatLinePreserved(t *testing.T) {
	src := "[Script Info]\nScriptType: v4.00\n\n[V4 Styles]\nFormat: Name, Fontname, Fontsize\nStyle: Default,Arial,20\n\n[Events]\nFormat: Marked, Start, End, Style, Text\nDialogue: Marked=0,0:00:01.00,0:00:02.00,Default,文本\n"
	doc := mustParseASS(t, src)
	out := mustSerializeASS(t, doc, ExportOptions{Format: FormatASS})
	if strings.Contains(out, "v4.00+") {
		t.Fatalf("v4.00 SSA 被升级成 V4+：%s", out)
	}
	if !strings.Contains(out, "Format: Marked, Start, End, Style, Text") {
		t.Fatalf("原 Events Format 行未保留：%s", out)
	}
	if !strings.Contains(out, "Format: Name, Fontname, Fontsize") {
		t.Fatalf("原 Styles Format 行未保留（不得强推 23 字段）：%s", out)
	}
	if !strings.Contains(out, "Dialogue: Marked=0,00:00:01.00,00:00:02.00,Default,文本") {
		t.Fatalf("Dialogue 字段数未与原 Format 对齐：%s", out)
	}
}

// B27：BOM 按长度优先判定 —— UTF-32 LE 前两字节与 UTF-16 LE 相同；
// UTF-16 BE 旧实现完全漏判（被当 GBK 解成乱码）。
func TestDetectEncodingBOMOrder(t *testing.T) {
	cases := []struct {
		name string
		raw  []byte
		want string
	}{
		{"utf16be", []byte{0xFE, 0xFF, 0x00, '1'}, "utf-16be"},
		{"utf32le", []byte{0xFF, 0xFE, 0x00, 0x00, '1', 0x00, 0x00, 0x00}, "utf-32le"}, // 必须早于 UTF-16 LE 判定
		{"utf16le", []byte{0xFF, 0xFE, '1', 0x00}, "utf-16le"},
		{"utf8bom", append([]byte{0xEF, 0xBB, 0xBF}, "1"...), "utf-8-bom"},
	}
	for _, c := range cases {
		text, got := DecodeText(c.raw)
		if got != c.want {
			t.Errorf("%s: 编码得到 %q，期望 %q", c.name, got, c.want)
			continue
		}
		if text != "1" {
			t.Errorf("%s: 解码文本 %q，期望 %q（BOM 未剥离或解码错位）", c.name, text, "1")
		}
	}
}

// mustParseLRC 用真实 parseLRC 构造 LRC 文档夹具。
func mustParseLRC(t *testing.T, src string) *SubtitleDoc {
	t.Helper()
	cues, err := parseLRC(src)
	if err != nil {
		t.Fatalf("parseLRC: %v", err)
	}
	return &SubtitleDoc{ID: "lrc-test", Format: FormatLRC, Encoding: "utf-8", Cues: cues}
}

// B28：offset 位移后 startMs 不得为负（钳到 0）。
// 夹具说明（相对 brief 的修正）：LRC 约定正 offset = 提前（parseLRC 内 offsetMs = -v），
// 故 [offset:5000] + [00:01.00] 使 offsetMs=-5000 → 1000-5000=-4000，正是「负位移导致负时间戳」的复现。
func TestLRCClampsNegativeStart(t *testing.T) {
	doc := mustParseLRC(t, "[offset:5000]\n[00:01.00]第一句\n")
	if doc.Cues[0].StartMs != 0 {
		t.Fatalf("负时间戳未钳制：%d（应为 0）", doc.Cues[0].StartMs)
	}
	// 导出兜底：手工构造的文档带负时间戳也不得写出非法 LRC 时间戳。
	out, err := NewEngine(nil).serializeLRC(
		&SubtitleDoc{ID: "x", Format: FormatLRC,
			Cues: []Cue{{Index: 1, StartMs: -123, EndMs: 100, Original: "句"}}},
		ExportOptions{Format: FormatLRC})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(out), "[00:00.00]句") {
		t.Fatalf("导出产出负时间戳：%s", out)
	}
}

// B28：serializeLRC 必须真正按双语模式分支。
func TestLRCBilingualBranch(t *testing.T) {
	doc := &SubtitleDoc{ID: "x", Format: FormatLRC,
		Cues: []Cue{{Index: 1, StartMs: 1000, EndMs: 2000, Original: "原文", Translated: "译文"}}}
	e := NewEngine(nil)
	for _, c := range []struct {
		mode BilingualMode
		want string
	}{
		{BilingualTranslationOnly, "[00:01.00]译文"},
		{BilingualDualLine, "[00:01.00]原文\n译文"},
		// keep-original 主文件为译文替换，原文另存由 ExportOriginal 写 .orig（app.go:790 注释）
		{BilingualKeepOriginal, "[00:01.00]译文"},
	} {
		out, err := e.serializeLRC(doc, ExportOptions{Format: FormatLRC, Bilingual: c.mode})
		if err != nil {
			t.Fatal(err)
		}
		if !strings.Contains(string(out), c.want) {
			t.Fatalf("双语模式 %s 输出错误：\n%s\n缺 %q", c.mode, out, c.want)
		}
	}
}
